from rest_framework.generics import ListAPIView
from rest_framework import permissions
from tenant_users.invites.models import TenantInvitation
from .serializers import TenantInvitationSerializer

class TenantInvitationListView(ListAPIView):
    serializer_class = TenantInvitationSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        tenant_id = self.request.query_params.get('tenant_id')
        if not tenant_id:
            return TenantInvitation.objects.none()

        return TenantInvitation.objects.filter(
            tenant_id=tenant_id,
            tenant__user_links__user=self.request.user
        )
